(()=>{'use strict';const root=document.getElementById('av-services-slider');if(!root)return;const track=root.querySelector('.sv-track'),cards=[...root.querySelectorAll('.sv-card')],prev=root.querySelector('[data-sv-prev]'),next=root.querySelector('[data-sv-next]'),count=root.querySelector('.sv-count');let index=0,frame;const update=()=>{let d=Infinity;cards.forEach((c,i)=>{let n=Math.abs(c.getBoundingClientRect().left-track.getBoundingClientRect().left-parseFloat(getComputedStyle(track).paddingLeft));if(n<d){d=n;index=i}});count.textContent=(index+1)+' / '+cards.length;prev.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-2};const go=dir=>{const c=cards[Math.max(0,Math.min(cards.length-1,index+dir))];track.scrollTo({left:c.offsetLeft-track.offsetLeft-parseFloat(getComputedStyle(track).paddingLeft),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));track.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(update)},{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(e.key==='ArrowRight'?1:-1)}});window.addEventListener('resize',update,{passive:true});update()})();
;(()=>{'use strict';const YT='https://www.youtube.com/@catalinsmaranda';const addYouTube=()=>{if(!document.getElementById('avf-youtube-premium-style')){const st=document.createElement('style');st.id='avf-youtube-premium-style';st.textContent='.avf-social-links a[data-network="youtube"]{position:relative;overflow:hidden;background:radial-gradient(circle at 18% 10%,rgba(94,170,235,.22),transparent 38%),linear-gradient(145deg,#07172d 0%,#0b2e57 48%,#061426 100%)!important;border:1px solid rgba(93,166,226,.58)!important;color:#eef7ff!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 10px 28px rgba(0,8,22,.38),0 0 18px rgba(40,109,170,.16)!important}.avf-social-links a[data-network="youtube"]:before{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 18%,rgba(255,255,255,.12) 45%,transparent 70%);transform:translateX(-130%);transition:transform .55s ease;pointer-events:none}.avf-social-links a[data-network="youtube"]:hover:before{transform:translateX(130%)}.avf-social-links a[data-network="youtube"]:hover{border-color:rgba(132,199,255,.9)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 12px 32px rgba(0,8,22,.46),0 0 24px rgba(54,132,202,.28)!important}.avf-youtube-mark{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:9px;background:linear-gradient(160deg,#174d79,#0b2748);border:1px solid rgba(154,211,255,.42);box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 0 12px rgba(59,137,205,.18);font-size:13px;line-height:1;color:#fff;text-shadow:0 0 8px rgba(255,255,255,.25)}';document.head.appendChild(st)}const nav=document.querySelector('.avf-social-links');if(nav&&!nav.querySelector('[data-network="youtube"]')){const a=document.createElement('a');a.href=YT;a.target='_blank';a.rel='noopener noreferrer';a.dataset.network='youtube';a.setAttribute('aria-label','AstroVip pe YouTube — Cătălin Smaranda');a.innerHTML='<span class="avf-youtube-mark" aria-hidden="true">▶</span><span>YouTube</span>';const tik=nav.querySelector('[data-network="tiktok"]');tik?tik.after(a):nav.appendChild(a)}};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',addYouTube,{once:true}):addYouTube()})();